using System.Net;using System.Text;using PowerXPlugin.Framework.Runtime.Common;using PowerXPlugin.Framework.Runtime.PluginRelease;using Xunit;
namespace PowerXPlugin.Framework.Tests.Runtime.PluginRelease;public sealed class PluginReleaseTests{const string T="00000000-0000-4000-8000-000000000001";[Fact]public async Task Delegated_uses_release_route_credential_and_tenant_boundary(){HttpRequestMessage? seen=null;var c=new PowerXPluginReleaseClient("https://core",T,new StaticServiceCredentialProvider(new ServiceCredential("sts")),new HttpClient(new H(r=>{seen=r;return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"data\":{\"session_uuid\":\"x\",\"plugin_id\":\"p\",\"status\":\"queued\"}}",Encoding.UTF8)};})));await c.StartInstallSessionAsync(new(T),new("pxp://artifact"));Assert.Equal("/api/v1/tenant/plugin-release/install-sessions",seen!.RequestUri!.AbsolutePath);Assert.Equal("Bearer sts",seen.Headers.Authorization!.ToString());var e=await Assert.ThrowsAsync<ReleaseException>(()=>c.StartInstallSessionAsync(new("00000000-0000-4000-8000-000000000002"),new("pxp://artifact")));Assert.Equal("FRAMEWORK_RELEASE_TENANT_MISMATCH",e.Code);}sealed class H(Func<HttpRequestMessage,HttpResponseMessage>f):HttpMessageHandler{protected override Task<HttpResponseMessage>SendAsync(HttpRequestMessage r,CancellationToken c)=>Task.FromResult(f(r));}}
